-- Local demo data only. Update exact original fixtures; preserve user edits and credentials.
BEGIN;
UPDATE content SET translations='{"ru": {"title": "Демо: образование Шымкента", "body": "<p>Единое пространство школ и детских садов Шымкента: новости, документы и контакты организаций города. Знакомимся с родным городом, учимся и заботимся о его зелёных пространствах. Демонстрационный материал.</p>"}, "kk": {"title": "Демо: Шымкенттің білім кеңістігі", "body": "<p>Шымкент мектептері мен балабақшаларына арналған бірыңғай білім кеңістігі. Ұйымды каталогтан тауып, жаңалықтар мен құжаттарды қараңыз. Бұл - демонстрациялық материал.</p>"}}'::jsonb WHERE translations='{"ru": {"title": "Демо: единый портал образования", "body": "<p>Демонстрационная версия портала. Найдите школы и детские сады в каталоге. Все сведения вымышлены.</p>"}, "kk": {"title": "Демо: бірыңғай білім порталы", "body": "<p>Бұл порталдың демонстрациялық нұсқасы. Мектептер мен балабақшаларды каталогтан табыңыз.</p>"}}'::jsonb AND (organization_id IS NULL OR organization_id IN (SELECT id FROM organizations WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled')));
UPDATE content SET translations='{"ru": {"title": "Демо: об организации", "body": "<h2>Образовательное пространство Шымкента</h2><p>Вымышленная образовательная организация для демонстрации городского портала.</p><ul><li>Обучение на казахском и русском языках</li><li>История и культура родного города</li><li>Забота о природе и учебные проекты</li></ul>"}, "kk": {"title": "Демо: ұйым туралы", "body": "<h2>Шымкенттегі білім кеңістігі</h2><p>Бұл - Шымкент қаласына арналған ойдан шығарылған білім беру ұйымы.</p><ul><li>Қазақ және орыс тілдеріндегі білім</li><li>Туған өлкенің тарихы мен мәдениеті</li><li>Қала табиғатына қамқорлық және оқу жобалары</li></ul>"}}'::jsonb WHERE translations='{"ru": {"title": "Демо: об организации", "body": "<h2>Наша организация</h2><p>Это вымышленная организация для проверки сайта.</p><ul><li>Казахский и русский языки</li><li>Новости, документы и галерея</li></ul>"}, "kk": {"title": "Демо: ұйым туралы", "body": "<h2>Біздің ұйым</h2><p>Бұл ойдан шығарылған ұйым. Сайтты тексеруге арналған мәліметтер.</p><ul><li>Қазақ және орыс тілдері</li><li>Жаңалықтар, құжаттар, галерея</li></ul>"}}'::jsonb AND (organization_id IS NULL OR organization_id IN (SELECT id FROM organizations WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled')));
UPDATE content SET translations='{"ru": {"title": "Демо: изучаем Шымкент вместе", "body": "<p>Учебные проекты о родном городе: история Шымкента, река Қошқар ата и дендропарк. Исследуем городские пространства и обсуждаем бережное отношение к природе.</p><p>Это пример вымышленного школьного проекта, не объявление о реальном мероприятии.</p>"}, "kk": {"title": "Демо: Шымкентті бірге танимыз", "body": "<p>Туған қаламызды танимыз: Шымкенттің тарихы, Қошқар ата өзені және дендросаябақ туралы оқу жобалары.</p><p>Бұл - ойдан шығарылған мектеп жобасының үлгісі, нақты іс-шара туралы хабарландыру емес.</p>"}}'::jsonb WHERE translations='{"ru": {"title": "Демо: день открытых дверей", "body": "<p>Добро пожаловать! Эта новость проверяет публикацию и отображение изображений.</p>"}, "kk": {"title": "Демо: ашық есік күні", "body": "<p>Сайтқа қош келдіңіз! Бұл жаңалық жариялау мен суреттерді көрсетуге арналған.</p>"}}'::jsonb AND (organization_id IS NULL OR organization_id IN (SELECT id FROM organizations WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled')));
UPDATE content SET translations='{"ru": {"title": "Демо: краеведение - река Қошқар ата", "body": "<p>Пример занятия по краеведению о реке Қошқар ата в Шымкенте: городской ландшафт, природа и забота о воде.</p><p>Демонстрационный материал. Казахский перевод пока не добавлен.</p>"}}'::jsonb WHERE translations='{"ru": {"title": "Демо: новость без казахского перевода", "body": "<p>Казахский перевод не заполнен намеренно. Переключите язык, чтобы проверить сообщение об отсутствии перевода.</p>"}}'::jsonb AND (organization_id IS NULL OR organization_id IN (SELECT id FROM organizations WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled')));
UPDATE content SET translations='{"ru": {"title": "Демо: Шымкент - наш город", "body": "<p>Три условные иллюстрации на тему образования и зелёных пространств Шымкента. Это не фотографии реальной организации.</p>"}, "kk": {"title": "Демо: Шымкент - біздің қаламыз", "body": "<p>Шымкенттегі білім мен табиғат тақырыбындағы үш шартты иллюстрация. Бұл нақты ұйымның фотосуреттері емес.</p>"}}'::jsonb WHERE translations='{"ru": {"title": "Демо: жизнь организации", "body": "<p>Три условные иллюстрации для проверки галереи. Это не фотографии реальной организации.</p>"}, "kk": {"title": "Демо: біздің күнделікті өміріміз", "body": "<p>Галереяны тексеруге арналған үш иллюстрация.</p>"}}'::jsonb AND (organization_id IS NULL OR organization_id IN (SELECT id FROM organizations WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled')));
UPDATE organizations SET name=jsonb_set(name,'{kk}',to_jsonb('Демо: Шымкент, №51 мектеп'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'kk'='Демо: №51 мектеп';
UPDATE organizations SET name=jsonb_set(name,'{ru}',to_jsonb('Демо: Шымкент, школа №51'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'ru'='Демо: школа №51';
UPDATE organizations SET name=jsonb_set(name,'{kk}',to_jsonb('Демо: Шымкент, №7 балабақша'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'kk'='Демо: №7 балабақша';
UPDATE organizations SET name=jsonb_set(name,'{ru}',to_jsonb('Демо: Шымкент, детский сад №7'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'ru'='Демо: детский сад №7';
UPDATE organizations SET name=jsonb_set(name,'{kk}',to_jsonb('Демо: Шымкент, №52 мектеп'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'kk'='Демо: №52 мектеп';
UPDATE organizations SET name=jsonb_set(name,'{ru}',to_jsonb('Демо: Шымкент, школа №52'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'ru'='Демо: школа №52';
UPDATE organizations SET name=jsonb_set(name,'{kk}',to_jsonb('Демо: Шымкент, өшірілген мектеп'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'kk'='Демо: өшірілген мектеп';
UPDATE organizations SET name=jsonb_set(name,'{ru}',to_jsonb('Демо: Шымкент, отключённая школа'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND name->>'ru'='Демо: отключённая школа';
UPDATE organizations SET profile=jsonb_set(profile,'{summary_kk}',to_jsonb('Шымкенттегі білім, туған өлкені тану және табиғатқа қамқорлық. Демонстрациялық ұйым: барлық мәліметтер ойдан шығарылған.'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND profile->>'summary_kk'='Демонстрациялық ұйым. Барлық мәліметтер ойдан шығарылған.';
UPDATE organizations SET profile=jsonb_set(profile,'{summary_ru}',to_jsonb('Образование в Шымкенте, краеведение и забота о природе родного города. Демонстрационная организация: все сведения вымышлены.'::text)) WHERE slug IN ('demo-school-51','demo-preschool-7','demo-school-52','demo-disabled') AND profile->>'summary_ru'='Демонстрационная организация. Все сведения вымышлены.';
UPDATE organizations SET name=jsonb_build_object('kk','Шымкент: №'||slug||CASE WHEN kind='school' THEN ' мектеп (демо)' ELSE ' балабақша (демо)' END,'ru','Шымкент: '||CASE WHEN kind='school' THEN 'школа №' ELSE 'детский сад №' END||slug||' (демо)'),profile=profile||jsonb_build_object('summary_kk','Шымкент қаласының порталына арналған ойдан шығарылған ұйым.','summary_ru','Вымышленная организация для демонстрации портала Шымкента.') WHERE slug ~ '^[0-9]+$' AND name=jsonb_build_object('kk',slug||' мектеп','ru','Школа № '||slug) AND profile='{"address_kk":"Шымкент","address_ru":"Шымкент"}'::jsonb;
UPDATE content SET translations='{"kk":{"title":"Шымкенттің білім порталы: демо нұсқа","body":"<p>Шымкент мектептері мен балабақшаларына арналған бірыңғай кеңістік. Бұл - тест материалы.</p>"},"ru":{"title":"Портал образования Шымкента: демоверсия","body":"<p>Единое пространство школ и детских садов Шымкента. Это тестовый материал.</p>"}}'::jsonb WHERE organization_id IS NULL AND translations='{"kk":{"title":"Білім порталы ашылды","body":"<p>Мектептер мен балабақшалардың ортақ кеңістігі.</p>"},"ru":{"title":"Портал образования открыт","body":"<p>Общее пространство школ и детских садов.</p>"}}'::jsonb;
COMMIT;
